#include <bits/stdc++.h>
using namespace std;

struct InputParams {
    long long mod;
    int n, m;
    bool read() {
        return !!(cin >> n >> m >> mod);
    }
};

struct OutputResult: InputParams {
    long long result;
    void print() {
        cout << result << "\n";
    }
};

namespace SolutionNS {
    struct Solver: OutputResult {
        long long binpow(long long base, long long exp) {
            long long res = 1;
            while (exp > 0) {
                if (exp & 1) res = res * base % mod;
                base = base * base % mod;
                exp >>= 1;
            }
            return res;
        }

        long long modInverse(long long x) {
            return binpow(x, mod - 2);
        }

        long long comb[503][503];

        pair<long long, long long> seq[504];
        pair<long long, long long> dp[504][504];

        void compute() {
            for (int i = 0; i <= n; ++i) {
                for (int j = 0; j <= n; ++j) {
                    if (i == 0 || j == 0) comb[i][j] = 1;
                    else comb[i][j] = (comb[i - 1][j] + comb[i][j - 1]) % mod;
                }
            }

            fill_n(seq, m + 1, make_pair(0, 0));
            seq[0] = {1, 0};
            for (int i = 1; i <= m; ++i) {
                for (int j = 0; j < i; ++j) {
                    pair<long long, long long> cur;
                    cur.first = seq[j].first * seq[i - 1 - j].first % mod;
                    cur.second = (seq[j].second * seq[i - 1 - j].first + seq[j].first * seq[i - 1 - j].second) % mod;
                    cur.second = (cur.second * (i + 1) + (ss(j) + ss(i - 1 - j)) * cur.first) % mod;
                    cur.first = cur.first * (i + 1) % mod;
                    cur.first = cur.first * comb[j][i - 1 - j] % mod;
                    cur.second = cur.second * comb[j][i - 1 - j] % mod;
                    seq[i].first = (seq[i].first + cur.first) % mod;
                    seq[i].second = (seq[i].second + cur.second) % mod;
                }
            }

            memset(dp, 0, sizeof dp);
            dp[0][0] = {1, 0};
            for (int i = 0; i <= n + 1; ++i) {
                for (int j = 0; j <= m; ++j) {
                    for (int k = 0; k <= min(n - i, m - j); ++k) {
                        pair<long long, long long> cur;
                        cur.first = seq[k].first * dp[i][j].first % mod;
                        cur.second = (seq[k].second * dp[i][j].first + seq[k].first * dp[i][j].second) % mod;
                        cur.first = cur.first * comb[j][k] % mod;
                        cur.second = cur.second * comb[j][k] % mod;
                        dp[i + k + 1][j + k].first = (dp[i + k + 1][j + k].first + cur.first) % mod;
                        dp[i + k + 1][j + k].second = (dp[i + k + 1][j + k].second + cur.second) % mod;
                    }
                }
            }
            result = dp[n + 1][m].second;
        }
        void reset_state() {
            *this = Solver();
        }
    };
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    SolutionNS::Solver sol;
    if (getenv("SG")) {
        freopen("problem.in", "r", stdin);
        while (sol.read()) {
            sol.compute();
            sol.print();
            sol.reset_state();
        }
    } else {
        sol.read();
        sol.compute();
        sol.print();
    }
    return 0;
}
